static bool MLHeroReserve15pn(std::atomic<unsigned long long> &attempts,
		const std::atomic<unsigned long long> &proofs) {
	unsigned long long attempt = attempts.load(std::memory_order_relaxed);
	while (attempt < ML_HERO_15PN_MAX_ATTEMPTS_PER_CLASS &&
			proofs.load(std::memory_order_relaxed) < ML_HERO_15PN_TARGET_PER_CLASS) {
		if (attempts.compare_exchange_weak(attempt, attempt + 1ull,
				std::memory_order_relaxed, std::memory_order_relaxed))
			return true;
	}
	return false;
}

static bool MLHeroRetain15pn(std::atomic<unsigned long long> &proofs) {
	unsigned long long proof = proofs.load(std::memory_order_relaxed);
	while (proof < ML_HERO_15PN_TARGET_PER_CLASS) {
		if (proofs.compare_exchange_weak(proof, proof + 1ull,
				std::memory_order_relaxed, std::memory_order_relaxed))
			return true;
	}
	return false;
}
