static bool MLHeroFiniteNonNegative15ob(const Spectrum &s) {
	return !s.IsNaN() && !s.IsInf() && !s.IsNeg();
}

static bool MLHeroRoughChildPayloadValid15ob(
		const MLHeroRoughChildPayload15ob &p) {
	if (p.laneCount < 2u || p.laneCount > 8u || p.lane >= p.laneCount ||
			!std::isfinite(p.lambda) || p.lambda < 380.f || p.lambda > 780.f ||
			!std::isfinite(p.wavelengthPdf) || !(p.wavelengthPdf > 0.f) ||
			!std::isfinite(p.wavelengthSampleWeight) ||
			p.wavelengthSampleWeight < 0.f ||
			!std::isfinite((double)p.direction.LengthSquared()) ||
			fabs((double)p.direction.LengthSquared() - 1.) > 2e-5 ||
			!MLHeroFiniteNonNegative15ob(p.wrappedValue) ||
			p.parentThroughput.IsNaN() || p.parentThroughput.IsInf() ||
			p.normalizedCandidateThroughput.IsNaN() ||
			p.normalizedCandidateThroughput.IsInf() ||
			!std::isfinite(p.scalarSampleMultiplier) ||
			p.scalarSampleMultiplier < 0. ||
			!std::isfinite(p.reconstructedScalarSampleMultiplier) ||
			p.reconstructedScalarSampleMultiplier < 0.)
		return false;
	const bool eventOK = (p.event & GLOSSY) && !(p.event & SPECULAR) &&
		(p.naturalTir ? ((p.event & REFLECT) && !(p.event & TRANSMIT)) :
			((p.event & TRANSMIT) && !(p.event & REFLECT)));
	if (!eventOK)
		return false;
	if (p.terminalZero)
		return !p.heroOwnerAnchored && p.wrappedValue.Black() && p.directPdf == 0. &&
			p.reversePdf == 0. && p.scalarSampleMultiplier == 0. &&
			p.reconstructedScalarSampleMultiplier == 0. &&
			p.normalizedCandidateThroughput.Black();
	return p.directPdf > 0. && std::isfinite(p.directPdf) &&
		p.reversePdf > 0. && std::isfinite(p.reversePdf);
}

