static u_int MLHeroPathBucket15ou(const unsigned long long bounces) {
	if (bounces < 4ull)
		return (u_int)bounces;
	if (bounces < 8ull)
		return 4u;
	if (bounces < 16ull)
		return 5u;
	if (bounces < 32ull)
		return 6u;
	if (bounces < 64ull)
		return 7u;
	if (bounces < 128ull)
		return 8u;
	return 9u;
}

static bool MLHeroDeterministicSplitContract15mg(const PathVertexVM &v,
	const u_int lane);
static float MLHeroRGBIllumSample380_780(const RGBColor &s,
	const float lambda);
static Spectrum MLHeroCIEEstimatorColor(const float lambda,
	const float sampleWeight);

static bool MLHeroPrivateEyeEndpoint15ox(Scene &scene,
		LightSourceConstRef light, const Spectrum &lightRadiance,
		const float directPdfA, const float emissionPdfW,
		const PathVertexVM &eye, const unsigned long long ticket,
		const u_int lane, const bool finiteLight,
		Spectrum *candidateOut15pd = nullptr) {
	if (candidateOut15pd)
		*candidateOut15pd = Spectrum();
	mlHero15oxEvaluations.fetch_add(1ull, std::memory_order_relaxed);
	const unsigned long long passDetail =
		mlHero15oxDetailTickets[finiteLight ? 1u : 0u].fetch_add(1ull,
			std::memory_order_relaxed);
	if (finiteLight)
		mlHero15oxFiniteEvaluations.fetch_add(1ull, std::memory_order_relaxed);
	else
		mlHero15oxInfiniteEvaluations.fetch_add(1ull, std::memory_order_relaxed);
	if (lightRadiance.Black())
		mlHero15oxBlackLights.fetch_add(1ull, std::memory_order_relaxed);

	const bool statePass = MLHeroDeterministicSplitContract15mg(eye, lane);
	if (!statePass)
		mlHero15oxStateFailures.fetch_add(1ull, std::memory_order_relaxed);
	const bool lightFinite = !lightRadiance.IsNaN() && !lightRadiance.IsInf();
	// Native DirectHitLight() terminates an exactly black light before reading
	// either PDF. Some finite area lights deliberately leave their emission PDF
	// at a negative sentinel in that zero-support case. Mirror that native
	// contract here: the detached endpoint is a valid physical zero, not a PDF
	// failure, and contributes no energy to the routed group.
	if (lightRadiance.Black()) {
		const bool zeroPass15pd = statePass && lightFinite;
		mlHero15oxZeroEnergyEndpoints.fetch_add(1ull,
			std::memory_order_relaxed);
		if (!lightFinite)
			mlHero15oxNonfinite.fetch_add(1ull, std::memory_order_relaxed);
		const unsigned long long detail15pd = zeroPass15pd ? passDetail :
			mlHero15oxFailureDetailTickets.fetch_add(1ull,
				std::memory_order_relaxed);
		if ((!zeroPass15pd && detail15pd < 64ull) ||
				(zeroPass15pd && detail15pd < 8ull)) {
			std::lock_guard<std::recursive_mutex> lock(mlHeroDebugLogMutex);
			FILE *f = MLHeroOpenAnyLog15gj("a");
			if (f) {
				fprintf(f,
					"phase15pd ROUGHGLASS_ZERO_ENERGY_ENDPOINT detail=%llu "
					"ticket=%llu lane=%u endpoint=%s lightID=%u lightType=%u "
					"depth=%u directPdfA=%.12g emissionPdfW=%.12g "
					"statePass=%u finitePass=%u candidate=(0,0,0) "
					"policy=NATIVE_DIRECTHIT_BLACK_EARLY_RETURN "
					"pdfSentinelIgnoredOnlyForExactBlack=1 energyAdded=0 "
					"productionWrites=0 pass=%u\n",
					detail15pd, ticket, lane,
					finiteLight ? "FINITE" : "INFINITE", light.GetID(),
					(u_int)light.GetType(), eye.depth, directPdfA, emissionPdfW,
					statePass ? 1u : 0u, lightFinite ? 1u : 0u,
					zeroPass15pd ? 1u : 0u);
				fclose(f);
			}
		}
		return zeroPass15pd;
	}
	const bool pdfPass = std::isfinite((double)directPdfA) && directPdfA >= 0.f &&
		std::isfinite((double)emissionPdfW) && emissionPdfW >= 0.f;

	const float lightPickPdf = scene.GetLightSources().GetEmitLightStrategy().
		SampleLightPdf(light, eye.bsdf.hitPoint.p,
			eye.bsdf.hitPoint.geometryN, eye.bsdf.IsVolume());
	const bool pickPdfPass = std::isfinite((double)lightPickPdf) &&
		lightPickPdf >= 0.f;
	if (!pdfPass || !pickPdfPass)
		mlHero15oxPdfFailures.fetch_add(1ull, std::memory_order_relaxed);

	const float directTerm = directPdfA * lightPickPdf;
	const float emissionTerm = emissionPdfW * lightPickPdf;
	// Exact BiDirCPU power heuristic, evaluated from the same float terms as
	// BiDirCPURenderThread::MIS() and accumulated in double for the audit.
	const double weightCamera =
		(double)(directTerm * directTerm) * (double)eye.dVCM +
		(double)(emissionTerm * emissionTerm) * (double)eye.dVC;
	const double misWeight = 1.0 / (weightCamera + 1.0);
	const bool misPass = std::isfinite(weightCamera) && weightCamera >= 0.0 &&
		std::isfinite(misWeight) && misWeight >= 0.0 && misWeight <= 1.0;
	if (!misPass)
		mlHero15oxMisFailures.fetch_add(1ull, std::memory_order_relaxed);

	const float lambda = eye.mlHeroLaneWaveLength[lane];
	const float sampleWeight = eye.mlHeroLaneSampleWeight[lane];
	const double eyeScalar = (double)eye.mlHeroLaneThroughput[lane].c[0];
	const RGBColor lightRGB(lightRadiance.c[0], lightRadiance.c[1],
		lightRadiance.c[2]);
	const double lightSPD =
		(double)MLHeroRGBIllumSample380_780(lightRGB, lambda);
	const double endpointScalar = eyeScalar * lightSPD * misWeight;
	const Spectrum candidate = MLHeroCIEEstimatorColor(lambda, sampleWeight) *
		(float)endpointScalar;
	if (!candidate.Black())
		mlHero15oxNonzeroCandidates.fetch_add(1ull, std::memory_order_relaxed);

	// A detached lane already owns T/N. Rebuild the equivalent legacy
	// packet-scaled value only as an audit identity; the live candidate is
	// deliberately not divided by N a second time.
	const Spectrum legacyExtraDiv = eye.mlHeroLaneCount > 0u ?
		candidate / (float)eye.mlHeroLaneCount : Spectrum(0.f);
	double normalizationError = 0.0;
	for (u_int channel = 0u; channel < 3u; ++channel) {
		const double actual = (double)candidate.c[channel];
		const double reconstructed = (double)legacyExtraDiv.c[channel] *
			(double)eye.mlHeroLaneCount;
		normalizationError = Max(normalizationError,
			fabs(actual - reconstructed) /
				Max(1e-20, Max(fabs(actual), fabs(reconstructed))));
	}
	const bool normalizationPass = eye.mlHeroLaneCount >= 2u &&
		eye.mlHeroLaneCount <= 8u && std::isfinite(normalizationError) &&
		normalizationError <= 2e-5;
	if (!normalizationPass)
		mlHero15oxNormalizationFailures.fetch_add(1ull,
			std::memory_order_relaxed);
	const bool finitePass = lightFinite && std::isfinite((double)lambda) &&
		std::isfinite((double)sampleWeight) && std::isfinite(eyeScalar) &&
		std::isfinite(lightSPD) && std::isfinite(endpointScalar) &&
		!candidate.IsNaN() && !candidate.IsInf();
	if (!finitePass)
		mlHero15oxNonfinite.fetch_add(1ull, std::memory_order_relaxed);
	const bool pass = statePass && pdfPass && pickPdfPass && misPass &&
		normalizationPass && finitePass;
	if (pass && candidateOut15pd)
		*candidateOut15pd = candidate;

	const unsigned long long detail = pass ? passDetail :
		mlHero15oxFailureDetailTickets.fetch_add(1ull,
			std::memory_order_relaxed);
	if ((!pass && detail < 64ull) || (pass && detail < 8ull)) {
		std::lock_guard<std::recursive_mutex> lock(mlHeroDebugLogMutex);
		FILE *f = MLHeroOpenAnyLog15gj("a");
		if (f) {
			fprintf(f,
				"phase15ox ROUGHGLASS_PRIVATE_EYE_ENDPOINT detail=%llu "
				"ticket=%llu lane=%u endpoint=%s lightID=%u lightType=%u "
				"depth=%u lambda=%.9g sampleWeight=%.9g eyeScalar=%.12g "
				"lightSPD=%.12g directPdfA=%.12g emissionPdfW=%.12g "
				"lightPickPdf=%.12g weightCamera=%.12g misWeight=%.12g "
				"candidate=(%.12g,%.12g,%.12g) normalizationRelError=%.12g "
				"statePass=%u pdfPass=%u misPass=%u normalizationPass=%u "
				"finitePass=%u privateValueOnly=1 sampleResultCreated=0 "
				"productionWrites=0 filmChanged=0 rendererPhysicsChanged=0 pass=%u\n",
				detail, ticket, lane, finiteLight ? "FINITE" : "INFINITE",
				light.GetID(), (u_int)light.GetType(), eye.depth, lambda,
				sampleWeight, eyeScalar, lightSPD, directPdfA, emissionPdfW,
				lightPickPdf, weightCamera, misWeight, candidate.c[0],
				candidate.c[1], candidate.c[2], normalizationError,
				statePass ? 1u : 0u, (pdfPass && pickPdfPass) ? 1u : 0u,
				misPass ? 1u : 0u, normalizationPass ? 1u : 0u,
				finitePass ? 1u : 0u, pass ? 1u : 0u);
			fclose(f);
		}
	}
	return pass;
}
