                                rayMint15gn = candidateRay15gn.mint;
                                rayTime15gn = candidateRay15gn.time;
                                rayValid15gn = std::isfinite(rayMint15gn) && rayMint15gn >= 0.f &&
                                    std::isfinite(rayTime15gn);
