        const bool finitePass15mh = lightFinite15mh &&
            std::isfinite((double)lambda15mh) &&
            std::isfinite((double)sampleWeight15mh) &&
            std::isfinite(eyeScalar15mh) && std::isfinite(lightSPD15mh) &&
            std::isfinite(endpointScalar15mh) &&
            !privateCandidate15mh.IsNaN() && !privateCandidate15mh.IsInf();
        if (!finitePass15mh)
            mlHero15mhNonfinite.fetch_add(1ull, std::memory_order_relaxed);
        if (!privateCandidate15mh.Black())
            mlHero15mhNonzeroCandidates.fetch_add(1ull,
                std::memory_order_relaxed);
        const bool pass15mh = statePass15mh && pdfPass15mh &&
            pickPdfPass15mh && misPass15mh && normalizationPass15mh &&
            finitePass15mh;
