    const bool groupAvailable15mf = !mlHeroShadowWorkQueue15mb.empty() &&
        productionParent15mf && productionRay15mf;
    std::chrono::steady_clock::time_point costStart15ot;
    if (costAudit15ot && groupAvailable15mf)
        costStart15ot = std::chrono::steady_clock::now();
    PathVertexVM groupSeed15mf;
    u_int groupSide15mf = 0u, groupLaneCount15mf = 0u;
