                        !recoveredTransport15md.IsInf() &&
                        !expectedTransport15md.IsNaN() &&
                        !expectedTransport15md.IsInf() &&
                        !splitEstimator15md.IsNaN() &&
                        !splitEstimator15md.IsInf() &&
                        std::isfinite(transportRelError15md) &&
                        std::isfinite(estimatorRelError15md) &&
                        std::isfinite(wavelengthPdfRelError15md);
