                            unsigned long long scan15ni =
                                mlHero15niScannedCandidates.load(
                                    std::memory_order_relaxed);
                            bool scanReserved15ni = false;
                            while (scan15ni < ML_HERO_15NI_MAX_SCANS) {
                                if (mlHero15niScannedCandidates.
                                        compare_exchange_weak(scan15ni,
                                            scan15ni + 1ull,
                                            std::memory_order_relaxed,
                                            std::memory_order_relaxed)) {
                                    scanReserved15ni = true;
                                    break;
                                }
                            }
                            if (!scanReserved15ni)
                                break;
                            const std::size_t lightIndex15ni =
                                (startLight15ni + lightOffset15ni) %
                                    lightCount15ni;
