                            bool ownerUnchanged15ni =
                                productionSampleResult15mj->filmX ==
                                    ownerFilmX15ni &&
                                productionSampleResult15mj->filmY ==
                                    ownerFilmY15ni &&
                                productionSampleResult15mj->radiance.Size() ==
                                    ownerBefore15ni.Size();
                            if (ownerUnchanged15ni)
                                for (u_int group15ni = 0u;
                                        group15ni < ownerBefore15ni.Size();
                                        ++group15ni)
                                    for (u_int channel15ni = 0u;
                                            channel15ni < 3u; ++channel15ni)
                                        ownerUnchanged15ni =
                                            ownerUnchanged15ni &&
                                            MLHeroFloatBits15lz(
                                                productionSampleResult15mj->
                                                    radiance[group15ni].
                                                        c[channel15ni]) ==
                                            MLHeroFloatBits15lz(
                                                ownerBefore15ni[group15ni].
                                                    c[channel15ni]);

                            Spectrum privateSum15ni(0.f);
                            bool onlyTarget15ni = true;
                            for (u_int group15ni = 0u;
                                    group15ni <
                                        privateSample15ni.radiance.Size();
                                    ++group15ni) {
                                privateSum15ni +=
                                    privateSample15ni.radiance[group15ni];
                                if ((!capture15ni.reachedContribution ||
                                        group15ni != capture15ni.lightID) &&
                                        !privateSample15ni.radiance[
                                            group15ni].Black())
                                    onlyTarget15ni = false;
                            }
                            const bool targetPass15ni =
                                capture15ni.reachedContribution ?
                                    capture15ni.lightID <
                                        privateSample15ni.radiance.Size() &&
                                    onlyTarget15ni :
                                    onlyTarget15ni &&
                                        privateSum15ni.Black();
                            double closureError15ni = 0.;
                            if (capture15ni.reachedContribution &&
                                    targetPass15ni) {
                                const Spectrum &actual15ni =
                                    privateSample15ni.radiance[
                                        capture15ni.lightID];
                                for (u_int channel15ni = 0u;
                                        channel15ni < 3u; ++channel15ni) {
                                    const double actual =
                                        actual15ni.c[channel15ni];
                                    const double captured =
                                        capture15ni.packetContribution.
                                            c[channel15ni];
                                    closureError15ni = Max(
                                        closureError15ni,
                                        fabs(actual - captured) /
                                            Max(1e-20, Max(fabs(actual),
                                                fabs(captured))));
                                }
                            } else if (!targetPass15ni)
                                closureError15ni = INFINITY;
                            const bool closurePass15ni =
                                std::isfinite(closureError15ni) &&
                                closureError15ni <= 2e-5;

                            double packet15ni[3], split15ni[3];
                            for (u_int channel15ni = 0u;
                                    channel15ni < 3u; ++channel15ni) {
                                packet15ni[channel15ni] =
                                    capture15ni.packetContribution.
                                        c[channel15ni];
                                split15ni[channel15ni] =
                                    capture15ni.splitContribution.
                                        c[channel15ni];
                            }
                            const slg::mlhero15ni::NormalizationProof
                                normalization15ni =
                                    slg::mlhero15ni::
                                        CheckPacketExtraDivision(packet15ni,
                                            split15ni,
                                            capture15ni.laneCount);
                            const bool statePass15ni =
                                MLHeroDeterministicSplitContract15mg(
                                    shadowVertex15lx,
                                    companionLane15lx) &&
                                (!capture15ni.reachedContribution ||
                                    capture15ni.splitContract);
                            const bool spectralVisible15ni =
                                capture15ni.reachedContribution &&
                                capture15ni.usedSpectral &&
                                !capture15ni.usedClassic;
                            const bool classicVisible15ni =
                                capture15ni.reachedContribution &&
                                capture15ni.usedClassic &&
                                !capture15ni.usedSpectral;
                            const bool branchClassified15ni =
                                !capture15ni.reachedContribution ||
                                spectralVisible15ni || classicVisible15ni;
                            const bool normalizationPass15ni =
                                !spectralVisible15ni ||
                                (capture15ni.splitCandidateReady &&
                                    !capture15ni.dualApplied &&
                                    normalization15ni.closes);
                            const bool finitePass15ni =
                                std::isfinite((double)u0_15ni) &&
                                !privateSample15ni.radiance.IsNaN() &&
                                !privateSample15ni.radiance.IsInf() &&
                                (!capture15ni.reachedContribution ||
                                    MLHeroFinite15ew(
                                        capture15ni.packetContribution)) &&
                                (!spectralVisible15ni ||
                                    (MLHeroFinite15ew(
                                        capture15ni.splitContribution) &&
                                     normalization15ni.finite));
                            const bool probePass15ni = spectralVisible15ni &&
                                branchClassified15ni && statePass15ni &&
                                targetPass15ni && closurePass15ni &&
                                normalizationPass15ni &&
                                ownerUnchanged15ni && finitePass15ni;

