                                MLHeroDeterministicSplitContract15mg(
                                    shadowVertex15lx, companionLane15lx);
                            const SpectrumGroup ownerBefore15ng =
                                productionSampleResult15mj->radiance;
                            const float ownerFilmX15ng =
                                productionSampleResult15mj->filmX;
                            const float ownerFilmY15ng =
                                productionSampleResult15mj->filmY;
                            SampleResult privateSample15ng =
                                *productionSampleResult15mj;
                            for (u_int group15ng = 0u;
                                    group15ng < privateSample15ng.radiance.Size();
                                    ++group15ng)
                                privateSample15ng.radiance[group15ng] =
                                    Spectrum(0.f);

